write('src/engine/validation/question-profile-validator.js', 'import { validateJsonSchema } from "./schema-validator.js";\nimport { validateQuestionVocabulary } from "./vocabulary-validator.js";\nimport { SPREADS } from "../../knowledge/spreads/definitions.js";\n\nfunction issue(code, path, message) { return Object.freeze({ code, path, keyword: "questionContract", message }); }\nexport function validateQuestionProfile(profile, schema) {\n  const errors = [...validateJsonSchema(profile, schema), ...validateQuestionVocabulary(profile)];\n  const dimensions = new Set(profile?.answerDimensions || []);\n  const conclusions = new Set(profile?.allowedConclusionTypes || []);\n  for (const spread of SPREADS) {\n    const spreadProfile = profile?.spreadProfiles?.[spread.id];\n    if (!spreadProfile) continue;\n    if (spreadProfile.spreadId !== spread.id) errors.push(issue("question.spread_id_mismatch", `$.spreadProfiles.${spread.id}.spreadId`, "Spread id must match object key."));\n    const expected = spread.positions.map((item) => item.id).sort();\n    const actual = (spreadProfile.positionRoles || []).map((item) => item.positionId).sort();\n    if (JSON.stringify(expected) !== JSON.stringify(actual)) errors.push(issue("question.position_coverage", `$.spreadProfiles.${spread.id}.positionRoles`, "Position responsibilities must cover the fixed spread exactly once."));\n    for (const [index, role] of (spreadProfile.positionRoles || []).entries()) {\n      for (const value of role.answerDimensions || []) if (!dimensions.has(value)) errors.push(issue("question.dimension_outside_profile", `$.spreadProfiles.${spread.id}.positionRoles[${index}].answerDimensions`, `Dimension ${value} is not declared by the question.`));\n      for (const value of role.conclusionResponsibilities || []) if (!conclusions.has(value)) errors.push(issue("question.conclusion_outside_profile", `$.spreadProfiles.${spread.id}.positionRoles[${index}].conclusionResponsibilities`, `Conclusion ${value} is not allowed by the question.`));\n    }\n  }\n  if (profile?.riskLevel === "elevated") {\n    for (const required of ["guaranteed-success", "investment-return", "certain-external-fact"]) if (!(profile.forbiddenClaims || []).includes(required)) errors.push(issue("question.elevated_risk_boundary", "$.forbiddenClaims", `Elevated-risk questions must forbid ${required}.`));\n  }\n  return errors.sort((a, b) => a.path.localeCompare(b.path) || a.code.localeCompare(b.code));\n}\n')
write('src/knowledge/questions/profiles/career-change.js', 'import { QUESTION_CLASSIFICATION_BY_ID } from "../classification.js";\n\nconst base = QUESTION_CLASSIFICATION_BY_ID["career-change"];\nconst conclusions = Object.freeze(["act-now", "act-with-conditions", "wait-and-prepare", "adjust-current-path", "currently-unfavorable", "indeterminate"]);\nconst forbidden = Object.freeze(["guaranteed-success", "exact-date", "certain-external-fact", "mind-reading", "inevitable-event"]);\nconst role = (positionId, answerDimensions, evidenceRoles, weight = 1) => Object.freeze({ positionId, answerDimensions: Object.freeze(answerDimensions), evidenceRoles: Object.freeze(evidenceRoles), conclusionResponsibilities: conclusions, weight });\n\nexport const QUESTION_PROFILE = Object.freeze({\n  schemaVersion: "1.0.0", id: base.id, text: base.text, domain: base.domain, intent: base.intent,\n  timeframe: base.timeframe, answerDimensions: base.answerDimensions, allowedConclusionTypes: conclusions,\n  forbiddenClaims: forbidden, riskLevel: base.riskLevel,\n  spreadProfiles: Object.freeze({\n    single: Object.freeze({ spreadId: "single", positionRoles: Object.freeze([role("essence", ["current-state", "recommended-action"], ["state", "reflection", "action"])]) }),\n    timeline: Object.freeze({ spreadId: "timeline", positionRoles: Object.freeze([\n      role("past", ["change-motivation"], ["cause", "motivation"], 0.9), role("present", ["current-readiness", "main-obstacle"], ["state", "obstacle"], 1.1), role("future", ["development-trend", "recommended-action"], ["trend", "outcome", "action"], 1),\n    ]) }),\n    cross: Object.freeze({ spreadId: "cross", positionRoles: Object.freeze([\n      role("core", ["current-readiness", "main-obstacle"], ["state", "obstacle"], 1.2), role("root", ["change-motivation"], ["cause", "motivation"], 0.9), role("trend", ["development-trend"], ["trend", "outcome"], 1), role("influence", ["external-condition", "main-obstacle"], ["resource", "opportunity", "obstacle"], 1), role("action", ["recommended-action"], ["action", "boundary"], 1.2),\n    ]) }),\n    celtic: Object.freeze({ spreadId: "celtic", positionRoles: Object.freeze([\n      role("present", ["current-state"], ["state"], 1.1), role("challenge", ["main-obstacle"], ["obstacle", "boundary"], 1.2), role("past", ["change-motivation"], ["cause", "motivation"], 0.8), role("future", ["development-trend"], ["trend", "outcome"], 1), role("above", ["current-readiness"], ["motivation", "opportunity"], 0.9), role("below", ["change-motivation"], ["cause", "reflection"], 0.9), role("advice", ["recommended-action"], ["action", "boundary"], 1.2), role("external", ["external-condition"], ["resource", "relationship"], 0.9), role("hopes", ["current-readiness"], ["reflection", "motivation"], 0.8), role("outcome", ["development-trend"], ["trend", "outcome"], 1.1),\n    ]) }),\n  }),\n  metadata: Object.freeze({ version: "1.0.0", status: "CONSUMER_VALIDATED", reviewDate: "2026-07-31" }),\n});\nexport default QUESTION_PROFILE;\n')
write('src/knowledge/schemas/position-operator.schema.json', '{\n  "$id": "https://astra.local/schemas/position-operator/1.0.0",\n  "$schema": "https://json-schema.org/draft/2020-12/schema",\n  "additionalProperties": false,\n  "properties": {\n    "actionTransform": {\n      "maxLength": 32,\n      "minLength": 1,\n      "type": "string"\n    },\n    "allowedConclusionResponsibilities": {\n      "items": {\n        "maxLength": 64,\n        "minLength": 1,\n        "type": "string"\n      },\n      "minItems": 1,\n      "type": "array",\n      "uniqueItems": true\n    },\n    "conditionality": {\n      "maxLength": 32,\n      "minLength": 1,\n      "type": "string"\n    },\n    "evidencePriority": {\n      "maxLength": 32,\n      "minLength": 1,\n      "type": "string"\n    },\n    "metadata": {\n      "additionalProperties": false,\n      "properties": {\n        "status": {\n          "enum": [\n            "DRAFT",\n            "SCHEMA_VALID",\n            "CONSUMER_VALIDATED",\n            "APPROVED"\n          ]\n        },\n        "version": {\n          "pattern": "^(?:0|[1-9][0-9]*)\\.(?:0|[1-9][0-9]*)\\.(?:0|[1-9][0-9]*)$",\n          "type": "string"\n        }\n      },\n      "required": [\n        "version",\n        "status"\n      ],\n      "type": "object"\n    },\n    "positionId": {\n      "maxLength": 64,\n      "minLength": 1,\n      "pattern": "^[a-z0-9]+(?:-[a-z0-9]+)*$",\n      "type": "string"\n    },\n    "schemaVersion": {\n      "const": "1.0.0"\n    },\n    "selectableRoles": {\n      "items": {\n        "maxLength": 32,\n        "minLength": 1,\n        "type": "string"\n      },\n      "minItems": 1,\n      "type": "array",\n      "uniqueItems": true\n    },\n    "spreadId": {\n      "maxLength": 32,\n      "minLength": 1,\n      "pattern": "^[a-z0-9]+(?:-[a-z0-9]+)*$",\n      "type": "string"\n    },\n    "subjectScope": {\n      "maxLength": 32,\n      "minLength": 1,\n      "type": "string"\n    },\n    "tense": {\n      "maxLength": 32,\n      "minLength": 1,\n      "type": "string"\n    },\n    "weight": {\n      "maximum": 2,\n      "minimum": 0.5,\n      "type": "number"\n    }\n  },\n  "required": [\n    "schemaVersion",\n    "spreadId",\n    "positionId",\n    "selectableRoles",\n    "tense",\n    "subjectScope",\n    "weight",\n    "conditionality",\n    "actionTransform",\n    "evidencePriority",\n    "allowedConclusionResponsibilities",\n    "metadata"\n  ],\n  "title": "Astra Tarot PositionOperator",\n  "type": "object"\n}\n')
write('src/knowledge/spreads/position-operators.js', 'const op = (spreadId, positionId, selectableRoles, tense, subjectScope, weight, conditionality, actionTransform, evidencePriority, allowedConclusionResponsibilities) => Object.freeze({ schemaVersion: "1.0.0", spreadId, positionId, selectableRoles: Object.freeze(selectableRoles), tense, subjectScope, weight, conditionality, actionTransform, evidencePriority, allowedConclusionResponsibilities: Object.freeze(allowedConclusionResponsibilities), metadata: Object.freeze({ version: "1.0.0", status: "CONSUMER_VALIDATED" }) });\nconst descriptive = ["descriptive", "conditional", "indeterminate"];\nconst advisory = ["act-now", "act-with-conditions", "wait-and-prepare", "adjust-current-path", "conditional", "indeterminate"];\nexport const POSITION_OPERATORS = Object.freeze([\n  op("single", "essence", ["state", "reflection", "action", "boundary"], "present", "self", 1, "contextual", "optional", "primary", [...descriptive, "focus", "caution"]),\n  op("timeline", "past", ["cause", "state", "motivation"], "past", "situation", 0.9, "contextual", "none", "supporting", descriptive),\n  op("timeline", "present", ["state", "obstacle", "resource"], "present", "situation", 1.1, "direct", "optional", "primary", descriptive),\n  op("timeline", "future", ["trend", "outcome", "action"], "near-future", "situation", 1, "path-dependent", "optional", "primary", [...descriptive, "growing", "slowing"]),\n  op("cross", "core", ["state", "obstacle", "motivation"], "present", "situation", 1.2, "direct", "none", "primary", descriptive),\n  op("cross", "root", ["cause", "motivation", "reflection"], "past", "self", 0.9, "contextual", "none", "supporting", descriptive),\n  op("cross", "trend", ["trend", "outcome", "opportunity"], "near-future", "situation", 1, "path-dependent", "optional", "primary", [...descriptive, "growing", "slowing", "restructuring"]),\n  op("cross", "influence", ["resource", "opportunity", "obstacle", "relationship"], "present", "mixed", 1, "contextual", "none", "supporting", descriptive),\n  op("cross", "action", ["action", "boundary", "resource"], "present", "self", 1.2, "advisory", "required", "primary", advisory),\n  op("celtic", "present", ["state", "motivation"], "present", "self", 1.1, "direct", "none", "primary", descriptive),\n  op("celtic", "challenge", ["obstacle", "boundary"], "present", "situation", 1.2, "direct", "optional", "primary", [...descriptive, "conflicted"]),\n  op("celtic", "past", ["cause", "state"], "past", "situation", 0.8, "contextual", "none", "contextual", descriptive),\n  op("celtic", "future", ["trend", "outcome"], "near-future", "situation", 1, "path-dependent", "optional", "primary", [...descriptive, "growing", "slowing"]),\n  op("celtic", "above", ["motivation", "opportunity", "reflection"], "timeless", "self", 0.9, "contextual", "none", "supporting", descriptive),\n  op("celtic", "below", ["cause", "motivation", "reflection"], "past", "self", 0.9, "contextual", "none", "supporting", descriptive),\n  op("celtic", "advice", ["action", "boundary", "resource"], "present", "self", 1.2, "advisory", "required", "primary", advisory),\n  op("celtic", "external", ["relationship", "resource", "obstacle"], "present", "external", 0.9, "contextual", "none", "supporting", descriptive),\n  op("celtic", "hopes", ["motivation", "reflection", "obstacle"], "present", "self", 0.8, "contextual", "none", "contextual", descriptive),\n  op("celtic", "outcome", ["trend", "outcome", "boundary"], "near-future", "situation", 1.1, "path-dependent", "optional", "primary", [...descriptive, "growing", "slowing", "restructuring"]),\n]);\nexport const POSITION_OPERATOR_BY_KEY = Object.freeze(Object.fromEntries(POSITION_OPERATORS.map((item) => [`${item.spreadId}:${item.positionId}`, item])));\n')
write('src/engine/validation/position-operator-validator.js', 'import { validateJsonSchema } from "./schema-validator.js";\nimport { validatePositionVocabulary } from "./vocabulary-validator.js";\nimport { SPREADS } from "../../knowledge/spreads/definitions.js";\nfunction issue(code, path, message) { return Object.freeze({ code, path, keyword: "positionContract", message }); }\nexport function validatePositionOperator(operator, schema) {\n  const errors = [...validateJsonSchema(operator, schema), ...validatePositionVocabulary(operator)];\n  const spread = SPREADS.find((item) => item.id === operator?.spreadId);\n  if (!spread) errors.push(issue("position.spread_unknown", "$.spreadId", "Position operator references an unknown spread."));\n  else if (!spread.positions.some((item) => item.id === operator.positionId)) errors.push(issue("position.position_unknown", "$.positionId", "Position id does not belong to the selected spread."));\n  if (operator?.actionTransform === "required" && !(operator.selectableRoles || []).includes("action")) errors.push(issue("position.action_role_required", "$.selectableRoles", "Required action transform must allow the action role."));\n  return errors.sort((a, b) => a.path.localeCompare(b.path) || a.code.localeCompare(b.code));\n}\nexport function validatePositionOperatorSet(operators, schema) {\n  const errors = [];\n  const seen = new Set();\n  for (const [index, operator] of operators.entries()) {\n    for (const item of validatePositionOperator(operator, schema)) errors.push(Object.freeze({ ...item, path: `$[${index}]${item.path.slice(1)}` }));\n    const key = `${operator.spreadId}:${operator.positionId}`;\n    if (seen.has(key)) errors.push(issue("position.duplicate", `$[${index}]`, `Duplicate operator ${key}.`));\n    seen.add(key);\n  }\n  const expected = SPREADS.flatMap((spread) => spread.positions.map((position) => `${spread.id}:${position.id}`)).sort();\n  const actual = [...seen].sort();\n  if (JSON.stringify(expected) !== JSON.stringify(actual)) errors.push(issue("position.coverage", "$", "Operator set must cover all fixed spread positions exactly once."));\n  return errors;\n}\n')
write('src/engine/observations/minimal-consumer.js', 'import { validateCardSemanticProfile } from "../validation/card-profile-validator.js";\nimport { validateCardVocabulary } from "../validation/vocabulary-validator.js";\nimport { validateQuestionProfile } from "../validation/question-profile-validator.js";\nimport { validatePositionOperator } from "../validation/position-operator-validator.js";\n\nfunction loadSchema(schema) { return schema; }\nfunction semanticMap(profile) { return new Map(Object.values(profile.facets).flat().map((unit) => [unit.id, unit])); }\nfunction roleOf(reference) { return reference.split(".", 1)[0]; }\nfunction stableSort(values) { return [...values].sort((a, b) => a.localeCompare(b, "en")); }\n\nexport function buildMinimalObservation({ profile, questionProfile, positionOperator, orientation = "upright", reversalMode = null, schemas }) {\n  const cardErrors = [...validateCardSemanticProfile(profile, loadSchema(schemas.card)), ...validateCardVocabulary(profile)];\n  const questionErrors = validateQuestionProfile(questionProfile, loadSchema(schemas.question));\n  const positionErrors = validatePositionOperator(positionOperator, loadSchema(schemas.position));\n  if (cardErrors.length || questionErrors.length || positionErrors.length) throw Object.assign(new Error("Consumer input validation failed."), { cardErrors, questionErrors, positionErrors });\n  const responsibility = questionProfile.spreadProfiles[positionOperator.spreadId].positionRoles.find((item) => item.positionId === positionOperator.positionId);\n  if (!responsibility) throw new Error("QuestionProfile does not define the selected position responsibility.");\n  const semantic = semanticMap(profile);\n  const domainRefs = profile.domains[questionProfile.domain].facetRefs;\n  let candidates = domainRefs.filter((ref) => positionOperator.selectableRoles.includes(roleOf(ref)) && responsibility.evidenceRoles.includes(roleOf(ref)));\n  let selectedReversalMode = null;\n  if (orientation === "reversed") {\n    selectedReversalMode = reversalMode || profile.reversal.supportedModes[0];\n    const reversalRefs = profile.reversal.modeFacetRefs[selectedReversalMode] || [];\n    const legal = reversalRefs.filter((ref) => positionOperator.selectableRoles.includes(roleOf(ref)) && semantic.has(ref));\n    if (legal.length) candidates = legal;\n  }\n  if (!candidates.length) {\n    candidates = Object.keys(profile.facets).filter((role) => positionOperator.selectableRoles.includes(role)).flatMap((role) => profile.facets[role].map((unit) => unit.id));\n  }\n  const semanticUnitRef = stableSort(candidates.filter((ref) => semantic.has(ref)))[0];\n  if (!semanticUnitRef) throw new Error("No legal semantic unit is available for this question and position.");\n  const unit = semantic.get(semanticUnitRef);\n  const dimensions = Object.freeze(Object.fromEntries(Object.entries(profile.dimensions).filter(([, value]) => value !== 0).slice(0, 5)));\n  return Object.freeze({\n    id: `obs:${profile.id}:${questionProfile.id}:${positionOperator.spreadId}:${positionOperator.positionId}:${orientation}`,\n    cardId: profile.id, questionId: questionProfile.id, spreadId: positionOperator.spreadId, positionId: positionOperator.positionId,\n    orientation, semanticUnitRef: `${profile.id}#${semanticUnitRef}`, selectedFacet: roleOf(semanticUnitRef), selectedReversalMode,\n    semanticTags: unit.tags, dimensions, localScore: Number((positionOperator.weight * (orientation === "reversed" ? 0.9 : 1)).toFixed(3)),\n    evidenceType: positionOperator.evidencePriority, responsibility: responsibility.answerDimensions[0],\n  });\n}\n')
write('docs/EVALUATION_PROTOCOL.md', '# Phase 1 评测、开发集与盲测保管协议\n\n## 1. 范围\n\nEV-000A只冻结评测协议、开发集结构、评分量表和最终盲测保管方式，不执行最终盲测。\n\n## 2. 数据分层\n\n- 开发集提交仓库，可用于调试Schema、词典、质量门禁和消费者契约。\n- 最终盲测正文不得进入仓库、日志、PR或普通代理上下文。\n- 盲测正文保存于CWapi受控目录；仓库只保留Schema、预期数量、政策、状态和内容哈希。\n- 盲测尚未物化时内容哈希必须为null，不得用占位文本伪造哈希。\n\n## 3. 评分\n\n单牌资料使用100分冻结量表：传统16、Facets 18、逆位14、牌位10、领域10、关系10、维度6、行动6、语言5、数据5。正式准入≥90，任一结构、来源或消费者错误均否决。\n\n## 4. 保管与失效\n\n盲测管理员与实现代理分离。输入适配器、Card/Question/Position契约、资料、词典、来源、权重或模板变化都会使已有结果失效。报告只保存汇总、分歧、版本和哈希，不保存隐藏正文。\n')
write('.qa/evaluation/rubric.json', '{\n  "admissionScore": 90,\n  "automaticVetoes": [\n    "schema-error",\n    "unregistered-source",\n    "unresolved-reference",\n    "consumer-failure",\n    "unsafe-deterministic-claim"\n  ],\n  "components": {\n    "action": 6,\n    "data": 5,\n    "dimensions": 6,\n    "domains": 10,\n    "facets": 18,\n    "language": 5,\n    "position": 10,\n    "relations": 10,\n    "reversal": 14,\n    "tradition": 16\n  },\n  "schemaVersion": "1.0.0"\n}\n')
