write('.qa/evaluation/development-set.json', '{\n  "cases": [\n    {\n      "cardId": "major-0",\n      "id": "dev-01",\n      "orientation": "upright",\n      "positionId": "core",\n      "questionId": "career-change",\n      "spreadId": "cross"\n    },\n    {\n      "cardId": "major-7",\n      "id": "dev-02",\n      "orientation": "reversed",\n      "positionId": "action",\n      "questionId": "career-change",\n      "spreadId": "cross"\n    },\n    {\n      "cardId": "major-9",\n      "id": "dev-03",\n      "orientation": "upright",\n      "positionId": "root",\n      "questionId": "career-change",\n      "spreadId": "cross"\n    },\n    {\n      "cardId": "major-16",\n      "id": "dev-04",\n      "orientation": "reversed",\n      "positionId": "trend",\n      "questionId": "career-change",\n      "spreadId": "cross"\n    },\n    {\n      "cardId": "cups-two",\n      "id": "dev-05",\n      "orientation": "upright",\n      "positionId": "influence",\n      "questionId": "career-change",\n      "spreadId": "cross"\n    },\n    {\n      "cardId": "pentacles-eight",\n      "id": "dev-06",\n      "orientation": "upright",\n      "positionId": "action",\n      "questionId": "career-change",\n      "spreadId": "cross"\n    }\n  ],\n  "datasetId": "phase-1-development",\n  "schemaVersion": "1.0.0"\n}\n')
write('tests/vocabulary_contract_test.mjs', 'import assert from "node:assert/strict";\nimport { THEME_TAG_IDS, TAG_ALIASES, VOCABULARY_REGISTRY } from "../src/knowledge/vocabularies/index.js";\nimport { SOURCE_IDS, SOURCE_REGISTRY } from "../src/knowledge/sources/registry.js";\nimport { INTERPRETATION_POLICY } from "../src/knowledge/policies/interpretation-policy.js";\nassert.equal(new Set(THEME_TAG_IDS).size, THEME_TAG_IDS.length);\nassert.ok(Object.keys(VOCABULARY_REGISTRY).length >= 16);\nassert.ok(SOURCE_IDS.length >= 6);\nassert.ok(SOURCE_IDS.every((id) => SOURCE_REGISTRY[id].status === "registered"));\nassert.ok(Object.values(TAG_ALIASES).every((id) => THEME_TAG_IDS.includes(id)));\nassert.ok(INTERPRETATION_POLICY.forbiddenDeterministicClaims.includes("medical-diagnosis"));\nconsole.log("TQ-002 vocabulary, source registry, aliases, and interpretation policy contract passed.");\n')
write('tests/evaluation_protocol_contract_test.mjs', 'import assert from "node:assert/strict";\nimport fs from "node:fs";\nconst read = (path) => JSON.parse(fs.readFileSync(path, "utf8"));\nconst rubric = read(".qa/evaluation/rubric.json");\nconst blind = read(".qa/evaluation/blind-set-manifest.json");\nconst development = read(".qa/evaluation/development-set.json");\nassert.equal(Object.values(rubric.components).reduce((a, b) => a + b, 0), 100);\nassert.equal(rubric.admissionScore, 90);\nassert.equal(blind.custody.repositoryContainsCases, false);\nassert.equal(blind.contentSha256, null);\nassert.equal(Object.hasOwn(blind, "cases"), false);\nassert.equal(development.cases.length, 6);\nconsole.log("EV-000A evaluation protocol and blind custody contract passed.");\n')
write('tests/golden_card_contract_test.mjs', 'import assert from "node:assert/strict";\nimport fs from "node:fs";\nimport { GOLDEN_CARD_PROFILES } from "../src/knowledge/cards/golden/index.js";\nimport { scoreCardProfile } from "../src/engine/validation/card-quality-gate.js";\nconst schema = JSON.parse(fs.readFileSync("src/knowledge/schemas/card-semantic-profile.schema.json", "utf8"));\nassert.deepEqual(GOLDEN_CARD_PROFILES.map((item) => item.id), ["major-0", "major-7", "major-9", "major-16", "cups-two", "pentacles-eight"]);\nfor (const profile of GOLDEN_CARD_PROFILES) {\n  const result = scoreCardProfile(profile, schema);\n  assert.equal(result.admitted, true, `${profile.id}: ${JSON.stringify(result)}`);\n  assert.ok(result.total >= 90);\n  assert.ok(Object.values(profile.facets).flat().length >= (profile.arcana === "major" ? 32 : 26));\n}\nconsole.log("TQ-003/TQ-004 golden profiles pass schema, vocabulary, and frozen >=90 quality gate.");\n')
write('tests/question_classification_contract_test.mjs', 'import assert from "node:assert/strict";\nimport { CATEGORIES } from "../src/knowledge/legacy/questions.js";\nimport { QUESTION_CLASSIFICATIONS, QUESTION_COVERAGE_MATRIX } from "../src/knowledge/questions/classification.js";\nconst expected = CATEGORIES.flatMap((category) => category.questions.map((item) => item.id));\nassert.deepEqual(QUESTION_CLASSIFICATIONS.map((item) => item.id), expected);\nassert.equal(QUESTION_CLASSIFICATIONS.length, 42);\nfor (const [domain, coverage] of Object.entries(QUESTION_COVERAGE_MATRIX)) { assert.equal(coverage.questionIds.length, 7, domain); assert.ok(coverage.intents.length >= 6, domain); }\nassert.ok(QUESTION_CLASSIFICATIONS.filter((item) => item.riskLevel === "elevated").every((item) => item.domain === "finance"));\nconsole.log("QP-001 classification and six-domain coverage matrix contract passed.");\n')
write('tests/question_profile_contract_test.mjs', 'import assert from "node:assert/strict";\nimport fs from "node:fs";\nimport { QUESTION_PROFILE } from "../src/knowledge/questions/profiles/career-change.js";\nimport { validateQuestionProfile } from "../src/engine/validation/question-profile-validator.js";\nconst schema = JSON.parse(fs.readFileSync("src/knowledge/schemas/question-profile.schema.json", "utf8"));\nassert.deepEqual(validateQuestionProfile(QUESTION_PROFILE, schema), []);\nconst broken = structuredClone(QUESTION_PROFILE); broken.spreadProfiles.cross.positionRoles.pop();\nassert.ok(validateQuestionProfile(broken, schema).some((item) => item.code === "question.position_coverage"));\nassert.equal(Object.keys(QUESTION_PROFILE.spreadProfiles).length, 4);\nconsole.log("QP-002 complete QuestionProfile schema and career-change profile contract passed.");\n')
write('tests/position_operator_contract_test.mjs', 'import assert from "node:assert/strict";\nimport fs from "node:fs";\nimport { POSITION_OPERATORS } from "../src/knowledge/spreads/position-operators.js";\nimport { validatePositionOperatorSet } from "../src/engine/validation/position-operator-validator.js";\nconst schema = JSON.parse(fs.readFileSync("src/knowledge/schemas/position-operator.schema.json", "utf8"));\nassert.equal(POSITION_OPERATORS.length, 19);\nassert.deepEqual(validatePositionOperatorSet(POSITION_OPERATORS, schema), []);\nassert.equal(new Set(POSITION_OPERATORS.map((item) => `${item.spreadId}:${item.positionId}`)).size, 19);\nconsole.log("PO-001 all 19 fixed Position Operators are complete and legal.");\n')
write('tests/consumer_contract_test.mjs', 'import assert from "node:assert/strict";\nimport fs from "node:fs";\nimport { GOLDEN_CARD_PROFILES } from "../src/knowledge/cards/golden/index.js";\nimport { QUESTION_PROFILE } from "../src/knowledge/questions/profiles/career-change.js";\nimport { POSITION_OPERATOR_BY_KEY } from "../src/knowledge/spreads/position-operators.js";\nimport { buildMinimalObservation } from "../src/engine/observations/minimal-consumer.js";\nconst schemas = Object.freeze({ card: JSON.parse(fs.readFileSync("src/knowledge/schemas/card-semantic-profile.schema.json", "utf8")), question: JSON.parse(fs.readFileSync("src/knowledge/schemas/question-profile.schema.json", "utf8")), position: JSON.parse(fs.readFileSync("src/knowledge/schemas/position-operator.schema.json", "utf8")) });\nconst originalRandom = Math.random; Math.random = () => { throw new Error("Consumer must not use random state."); };\ntry {\n  for (const profile of GOLDEN_CARD_PROFILES) {\n    const core = buildMinimalObservation({ profile, questionProfile: QUESTION_PROFILE, positionOperator: POSITION_OPERATOR_BY_KEY["cross:core"], schemas });\n    const action = buildMinimalObservation({ profile, questionProfile: QUESTION_PROFILE, positionOperator: POSITION_OPERATOR_BY_KEY["cross:action"], schemas });\n    const reversed = buildMinimalObservation({ profile, questionProfile: QUESTION_PROFILE, positionOperator: POSITION_OPERATOR_BY_KEY["cross:action"], orientation: "reversed", schemas });\n    assert.ok(core.semanticUnitRef.startsWith(`${profile.id}#`)); assert.ok(action.semanticUnitRef.startsWith(`${profile.id}#`));\n    assert.notEqual(core.selectedFacet, action.selectedFacet); assert.ok(reversed.selectedReversalMode); assert.ok(Number.isFinite(reversed.localScore));\n    assert.deepEqual(core, buildMinimalObservation({ profile, questionProfile: QUESTION_PROFILE, positionOperator: POSITION_OPERATOR_BY_KEY["cross:core"], schemas }));\n  }\n} finally { Math.random = originalRandom; }\nconsole.log("TQ-005A/TQ-005B formal fixtures produce deterministic legal minimal Observations without consuming random state.");\n')
write('tests/phase_1_gate_test.mjs', 'import assert from "node:assert/strict";\nimport fs from "node:fs";\nimport crypto from "node:crypto";\nconst required = [\n  "src/knowledge/vocabularies/index.js", "src/knowledge/sources/registry.js", "docs/EVALUATION_PROTOCOL.md",\n  "src/knowledge/cards/golden/index.js", "src/engine/validation/card-quality-gate.js",\n  "src/knowledge/questions/classification.js", "src/knowledge/schemas/question-profile.schema.json",\n  "src/knowledge/schemas/position-operator.schema.json", "src/engine/observations/minimal-consumer.js",\n  ".qa/evaluation/golden-set-manifest.json", ".qa/evaluation/contract-fingerprint.json",\n];\nfor (const path of required) assert.ok(fs.existsSync(path), path);\nconst progress = fs.readFileSync("docs/PROGRESS.md", "utf8");\nassert.match(progress, /Phase 1状态 \\| `PARENT-DONE`/);\nassert.match(progress, /`TQ-101A`/);\nconst contract = JSON.parse(fs.readFileSync(".qa/evaluation/contract-fingerprint.json", "utf8"));\nassert.equal(contract.schemaVersion, "1.0.0");\nassert.match(contract.combinedSha256, /^[a-f0-9]{64}$/);\nconst manifest = JSON.parse(fs.readFileSync(".qa/evaluation/golden-set-manifest.json", "utf8"));\nassert.equal(manifest.cards.length, 6);\nassert.ok(manifest.cards.every((item) => item.score >= 90 && /^[a-f0-9]{64}$/.test(item.profileSha256)));\nconsole.log("Phase 1 terminal gate passed: vocabularies, evaluation, golden cards, QuestionProfile, Position Operators, and consumer fingerprints are frozen.");\n')
write('scripts/generate_phase_1_manifests.mjs', '#!/usr/bin/env node\nimport crypto from "node:crypto";\nimport fs from "node:fs";\nimport { GOLDEN_CARD_PROFILES } from "../src/knowledge/cards/golden/index.js";\nimport { QUESTION_PROFILE } from "../src/knowledge/questions/profiles/career-change.js";\nimport { POSITION_OPERATORS } from "../src/knowledge/spreads/position-operators.js";\nimport { VOCABULARY_REGISTRY } from "../src/knowledge/vocabularies/index.js";\nimport { SOURCE_REGISTRY } from "../src/knowledge/sources/registry.js";\nimport { scoreCardProfile } from "../src/engine/validation/card-quality-gate.js";\nconst stable = (value) => Array.isArray(value) ? value.map(stable) : value && typeof value === "object" ? Object.fromEntries(Object.keys(value).sort().map((key) => [key, stable(value[key])])) : value;\nconst text = (value) => `${JSON.stringify(stable(value), null, 2)}\\n`;\nconst hash = (value) => crypto.createHash("sha256").update(typeof value === "string" ? value : text(value)).digest("hex");\nconst cardSchema = JSON.parse(fs.readFileSync("src/knowledge/schemas/card-semantic-profile.schema.json", "utf8"));\nconst questionSchema = JSON.parse(fs.readFileSync("src/knowledge/schemas/question-profile.schema.json", "utf8"));\nconst positionSchema = JSON.parse(fs.readFileSync("src/knowledge/schemas/position-operator.schema.json", "utf8"));\nconst golden = { schemaVersion: "1.0.0", generatedBy: "scripts/generate_phase_1_manifests.mjs", cards: GOLDEN_CARD_PROFILES.map((profile) => ({ id: profile.id, score: scoreCardProfile(profile, cardSchema).total, profileSha256: hash(profile) })) };\nconst parts = { cardSchema: hash(cardSchema), vocabulary: hash(VOCABULARY_REGISTRY), sources: hash(SOURCE_REGISTRY), questionSchema: hash(questionSchema), questionProfile: hash(QUESTION_PROFILE), positionSchema: hash(positionSchema), positionOperators: hash(POSITION_OPERATORS) };\nconst contract = { schemaVersion: "1.0.0", generatedBy: "scripts/generate_phase_1_manifests.mjs", parts, combinedSha256: hash(parts), invalidatesConsumerValidationWhenChanged: Object.keys(parts) };\nconst outputs = new Map([[".qa/evaluation/golden-set-manifest.json", text(golden)], [".qa/evaluation/contract-fingerprint.json", text(contract)]]);\nconst check = process.argv.includes("--check"); let failed = false;\nfor (const [path, content] of outputs) { if (check) { if (!fs.existsSync(path) || fs.readFileSync(path, "utf8").replace(/\\r\\n?/g, "\\n") !== content) { console.error(`${path}: stale`); failed = true; } } else { fs.mkdirSync(path.slice(0, path.lastIndexOf("/")), { recursive: true }); fs.writeFileSync(path, content, "utf8"); } }\nconsole.log(JSON.stringify({ mode: check ? "check" : "write", goldenCards: golden.cards.length, combinedSha256: contract.combinedSha256 })); if (failed) process.exitCode = 1;\n')
write('src/knowledge/cards/golden/index.js', 'import { CARD_PROFILE as MAJOR_0 } from "./major-0.js";\nimport { CARD_PROFILE as MAJOR_7 } from "./major-7.js";\nimport { CARD_PROFILE as MAJOR_9 } from "./major-9.js";\nimport { CARD_PROFILE as MAJOR_16 } from "./major-16.js";\nimport { CARD_PROFILE as CUPS_TWO } from "./cups-two.js";\nimport { CARD_PROFILE as PENTACLES_EIGHT } from "./pentacles-eight.js";\n\nexport const GOLDEN_CARD_PROFILES = Object.freeze([MAJOR_0, MAJOR_7, MAJOR_9, MAJOR_16, CUPS_TWO, PENTACLES_EIGHT]);\nexport const GOLDEN_CARD_BY_ID = Object.freeze(Object.fromEntries(GOLDEN_CARD_PROFILES.map((item) => [item.id, item])));\n')
write('docs/PROGRESS.md', '# 项目开发进度\n\n> 本文件是继续任务的唯一实时状态入口；任务定义以 `EXECUTION_CONTRACTS.md` 为准。\n\n## 当前状态\n\n| 项目 | 当前值 |\n|---|---|\n| 当前阶段 | Phase 2：78张牌资料升级 |\n| 当前进行中任务 | 无 |\n| 最近完成任务 | Phase 1：数据、问题和牌位契约基础 |\n| 唯一下一任务 | `TQ-101A` 大阿卡纳第一批 |\n| 阻塞项 | 无 |\n| 工作分支 | `phase-1-completion` |\n| Phase M状态 | `PARENT-DONE` |\n| Phase 1状态 | `PARENT-DONE` |\n| Phase 2状态 | `PARENT-IN-PROGRESS` |\n| 最后更新时间 | 2026-07-31 |\n\n## Phase 1完成记录\n\n| 任务 | 状态 | 产物 |\n|---|---|---|\n| `TQ-001` | `DONE` | CardSemanticProfile Draft 2020-12 Schema与结构验证器 |\n| `TQ-002` | `DONE` | 正式词典、来源注册和解释政策 |\n| `EV-000A` | `DONE` | 开发集、100分量表和外部盲测保管协议 |\n| `TQ-003` | `DONE` | 愚者、战车、隐者、高塔、圣杯二、星币八六张黄金资料 |\n| `TQ-004` | `DONE` | 质量门禁、冻结manifest，六张均≥90 |\n| `QP-001` | `DONE` | 42题分类和六领域覆盖矩阵 |\n| `QP-002` | `DONE` | 完整QuestionProfile Schema与career-change正式profile |\n| `PO-001` | `DONE` | 四牌阵19个Position Operator完整契约 |\n| `TQ-005A` | `DONE` | 从正式Card/Question/Position契约建立消费者夹具 |\n| `TQ-005B` | `DONE` | 六张黄金样本可消费性和最小Observation验证 |\n\n## 冻结不变量\n\n- 78张牌、42个固定问题、1/3/5/10牌阵、公开ID、旧历史键和随机分布不变。\n- 人工JS/CSS无超限技术债；不引入npm依赖、构建步骤或GitHub Actions。\n- Card、Question和Position契约、词典、来源、黄金样本与消费者指纹变化会使TQ-005B失效。\n- 最终盲测正文不进入仓库；当前只冻结保管政策、Schema、数量和未物化状态。\n- `automation/validate.py --scope full` 是完整回归入口。\n\n## 唯一NEXT：TQ-101A\n\n完成 `major-1`、`major-2`、`major-3`、`major-4`、`major-5` 五张正式资料，不修改黄金卡、Schema、QuestionProfile或Position Operator。\n')
