write('src/knowledge/cards/golden/major-7.js', 'import { buildGoldenCardProfile } from "../profile-builder.js";\n\nexport const CARD_PROFILE = buildGoldenCardProfile({"name":"战车","arcana":"major","number":7,"coreArchetype":"驾驭相反力量并朝共同目标推进","essence":"方向、整合、纪律与负责的推进","developmentalStage":"从意愿形成进入主动控制与持续执行","strength":"统一方向并整合分散力量","shadow":"用力失衡、急于证明与目标摇摆","practice":"写下唯一阶段目标并删除一个无关消耗","origin":"多个动机或外部要求同时争夺控制权","goal":"让行动、资源与价值指向同一目标","boundary":"速度不能替代方向判断","relationship":"明确共同目标和各自负责范围","resource":"意志、组织能力与推进节奏","transition":"从分散拉扯进入可控推进","outcome":"在条件协调后形成稳定进展","themes":["direction","agency","control","movement"],"conflicts":["uncertainty","impulsiveness"],"stageTags":["movement","integration"],"reversalModes":["blocked","misdirected","loss-of-control"],"dimensions":{"activation":3,"stability":1,"clarity":2,"agency":3,"openness":0,"reciprocity":0,"materiality":0,"emotionality":-1,"risk":1,"transition":2,"speed":3},"keywordsUpright":["方向","整合","推进"],"keywordsReversed":["失控","摇摆","蛮力"],"uprightSummary":"不同力量可以被清晰方向和稳定纪律整合，推进建立在负责的控制之上。","reversedSummary":"速度、控制或证明欲正在脱离目标，需要重新统一方向并恢复反馈。","id":"major-7","symbols":[{"id":"chariot","symbol":"战车","meaning":"主动承担方向与推进责任","traditionScopes":["cross-deck","historical"]},{"id":"paired-forces","symbol":"成对力量","meaning":"相反动力需要被整合而非压制","traditionScopes":["rws","marseille"]},{"id":"city","symbol":"身后城市","meaning":"离开既有秩序意味着承担自主选择","traditionScopes":["rws"]}],"sources":["waite-pictorial-key-1910","pollack-seventy-eight-degrees-1978","project-cross-deck-baseline","project-modernization-policy"]});\nexport default CARD_PROFILE;\n')
write('src/knowledge/cards/golden/major-9.js', 'import { buildGoldenCardProfile } from "../profile-builder.js";\n\nexport const CARD_PROFILE = buildGoldenCardProfile({"name":"隐者","arcana":"major","number":9,"coreArchetype":"通过有期限的独处提炼可靠判断","essence":"内省、辨别、经验与节制的退后","developmentalStage":"从外部评价退回内在标准并形成个人智慧","strength":"安静观察并提炼经验","shadow":"孤立、封闭与无休止反刍","practice":"设定结束时间的独处记录与外部验证","origin":"外界噪声或旧答案无法回应当前课题","goal":"形成能够解释事实与感受的独立判断","boundary":"独处必须有期限并保留现实连接","relationship":"说明需要空间而不是突然切断联系","resource":"经验、耐心与细节辨别力","transition":"从噪声反应进入沉静判断","outcome":"得到可以被现实检验的内在方向","themes":["introspection","solitude","discernment","wisdom"],"conflicts":["isolation","uncertainty"],"stageTags":["reflection","clarity"],"reversalModes":["blocked","internalized","avoided"],"dimensions":{"activation":-2,"stability":2,"clarity":2,"agency":1,"openness":-1,"reciprocity":-1,"materiality":-1,"emotionality":1,"risk":0,"transition":1,"speed":-3},"keywordsUpright":["内省","辨别","独处"],"keywordsReversed":["孤立","反刍","封闭"],"uprightSummary":"主动退后可以让经验沉淀成判断，但独处的价值来自清晰目标与现实验证。","reversedSummary":"独处可能变成隔绝或反复思考，需要恢复期限、反馈和具体行动。","id":"major-9","symbols":[{"id":"lantern","symbol":"灯笼","meaning":"有限光线强调一步一证据的辨别","traditionScopes":["rws","historical"]},{"id":"staff","symbol":"手杖","meaning":"经验提供支撑而不是替代行走","traditionScopes":["rws"]},{"id":"mountain","symbol":"高处","meaning":"距离带来视角也可能造成隔离","traditionScopes":["rws","modernized"]}],"sources":["waite-pictorial-key-1910","pollack-seventy-eight-degrees-1978","project-cross-deck-baseline","project-modernization-policy"]});\nexport default CARD_PROFILE;\n')
write('src/knowledge/cards/golden/major-16.js', 'import { buildGoldenCardProfile } from "../profile-builder.js";\n\nexport const CARD_PROFILE = buildGoldenCardProfile({"name":"高塔","arcana":"major","number":16,"coreArchetype":"失效结构被事实打破后重新建立可靠基础","essence":"揭露、断裂、释放与安全重建","developmentalStage":"从维护脆弱假设转向承认事实并重构系统","strength":"让真相暴露结构性问题","shadow":"恐慌、破坏冲动与灾难化解释","practice":"先处理安全与事实，再分阶段重建","origin":"长期积累的矛盾超过旧结构承载能力","goal":"停止维护已经失效的假设","boundary":"危机中优先人身、财务和信息安全","relationship":"区分事实冲突与对人格的全面否定","resource":"诚实、应急能力与重新设计的空间","transition":"从脆弱稳定进入结构性重组","outcome":"旧结构退出后形成更透明的基础","themes":["truth","disruption","release","rebuilding"],"conflicts":["panic","stability"],"stageTags":["disruption","renewal"],"reversalModes":["blocked","internalized","released","avoided"],"dimensions":{"activation":3,"stability":-3,"clarity":3,"agency":-1,"openness":1,"reciprocity":-1,"materiality":-1,"emotionality":3,"risk":3,"transition":3,"speed":3},"keywordsUpright":["揭露","断裂","重建"],"keywordsReversed":["压抑危机","灾难化","拒绝事实"],"uprightSummary":"被忽视的事实正在突破旧结构，首要任务是保护安全、确认损失并重建可靠基础。","reversedSummary":"危机可能被压抑、内化或反复预演，需要区分真实风险与灾难化想象。","id":"major-16","symbols":[{"id":"lightning","symbol":"闪电","meaning":"突发事实突破人为控制","traditionScopes":["rws","historical"]},{"id":"crown","symbol":"坠落王冠","meaning":"僵化权威和错误确定性被移除","traditionScopes":["rws"]},{"id":"falling-figures","symbol":"坠落人物","meaning":"结构失败会影响身处其中的人","traditionScopes":["rws","modernized"]}],"sources":["waite-pictorial-key-1910","pollack-seventy-eight-degrees-1978","project-cross-deck-baseline","project-modernization-policy"]});\nexport default CARD_PROFILE;\n')
write('src/knowledge/cards/golden/cups-two.js', 'import { buildGoldenCardProfile } from "../profile-builder.js";\n\nexport const CARD_PROFILE = buildGoldenCardProfile({"name":"圣杯二","arcana":"minor","suit":"cups","rank":"two","coreArchetype":"两个主体在差异中建立可回应的互惠连接","essence":"相遇、互惠、沟通与平等协商","developmentalStage":"从个体情感走向可被双方确认的关系","strength":"建立互相回应的连接","shadow":"投射、失衡与把期待当成共识","practice":"进行一次包含需求、边界和确认的对话","origin":"双方都感受到连接或合作的可能","goal":"形成尊重差异的双向承诺","boundary":"亲近不能取消个人选择和退出权","relationship":"用具体回应代替猜测对方心意","resource":"共情、吸引力与协商意愿","transition":"从单向期待进入双向确认","outcome":"建立可持续的合作或亲密基础","themes":["reciprocity","communication","balance","partnership"],"conflicts":["projection","isolation"],"stageTags":["relationship","cooperation"],"reversalModes":["blocked","deficient","distorted"],"dimensions":{"activation":1,"stability":1,"clarity":1,"agency":1,"openness":2,"reciprocity":3,"materiality":0,"emotionality":3,"risk":0,"transition":1,"speed":0},"keywordsUpright":["互惠","相遇","协商"],"keywordsReversed":["失衡","投射","断联"],"uprightSummary":"连接的价值来自双方真实回应、平等协商和边界清晰，而不只是强烈感受。","reversedSummary":"期待、回应或权力出现不对称，需要停止猜测并确认双方实际意愿。","id":"cups-two","symbols":[{"id":"paired-cups","symbol":"双杯","meaning":"情感和承诺需要双向交换","traditionScopes":["rws","cross-deck"]},{"id":"caduceus","symbol":"交缠杖","meaning":"差异可以通过沟通形成动态平衡","traditionScopes":["rws"]},{"id":"lion-head","symbol":"狮首","meaning":"吸引力需要被成熟边界承载","traditionScopes":["rws","modernized"]}],"sources":["waite-pictorial-key-1910","pollack-seventy-eight-degrees-1978","project-cross-deck-baseline","project-modernization-policy"]});\nexport default CARD_PROFILE;\n')
write('src/knowledge/cards/golden/pentacles-eight.js', 'import { buildGoldenCardProfile } from "../profile-builder.js";\n\nexport const CARD_PROFILE = buildGoldenCardProfile({"name":"星币八","arcana":"minor","suit":"pentacles","rank":"eight","coreArchetype":"通过有反馈的重复练习把能力转化为可靠成果","essence":"技艺、专注、迭代与长期质量","developmentalStage":"从基础掌握进入 deliberate practice 与稳定产出","strength":"以反馈驱动的持续练习","shadow":"机械重复、完美主义与只顾产量","practice":"选择一个指标完成一轮练习、反馈和修正","origin":"目标要求比当前熟练度更稳定的能力","goal":"把零散经验转化为可复用技艺","boundary":"练习必须包含休息、反馈和质量标准","relationship":"在合作中明确评审标准与改进方式","resource":"耐心、手工能力与可累计的时间","transition":"从尝试进入稳定的技能建构","outcome":"形成可证明、可复用的专业能力","themes":["craft","practice","mastery","diligence"],"conflicts":["perfectionism","repetition"],"stageTags":["learning","quality"],"reversalModes":["blocked","excessive","misdirected"],"dimensions":{"activation":2,"stability":3,"clarity":2,"agency":2,"openness":0,"reciprocity":0,"materiality":3,"emotionality":-1,"risk":-1,"transition":1,"speed":-1},"keywordsUpright":["练习","技艺","精进"],"keywordsReversed":["机械重复","完美主义","低效"],"uprightSummary":"稳定成果来自明确标准、重复练习和及时反馈，耐心会把努力转化为技艺。","reversedSummary":"重复可能失去反馈或被完美主义绑架，需要重新定义质量、节奏和停止条件。","id":"pentacles-eight","symbols":[{"id":"workbench","symbol":"工作台","meaning":"技能在具体任务中被反复检验","traditionScopes":["rws","cross-deck"]},{"id":"repeated-coins","symbol":"排列星币","meaning":"成果来自可累计的重复与修正","traditionScopes":["rws"]},{"id":"distant-town","symbol":"远处城镇","meaning":"专注训练暂时减少外界参与但应服务现实生活","traditionScopes":["rws","modernized"]}],"sources":["waite-pictorial-key-1910","pollack-seventy-eight-degrees-1978","project-cross-deck-baseline","project-modernization-policy"]});\nexport default CARD_PROFILE;\n')

